import{_ as s,o as a,c as i,a2 as t}from"./chunks/framework.CWWEQfK7.js";const k=JSON.parse('{"title":"Basic configuration: start the service safely","description":"Prepare the database, secrets, service addresses, and browser access settings required to start the Ershu API, then verify them with concrete results.","frontmatter":{"page_id":"configuration-basic","title":"Basic configuration: start the service safely","description":"Prepare the database, secrets, service addresses, and browser access settings required to start the Ershu API, then verify them with concrete results."},"headers":[],"relativePath":"en/configuration/basic.md","filePath":"en/configuration/basic.md","lastUpdated":1786290726000}'),n={name:"en/configuration/basic.md"};function r(l,e,d,o,p,h){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="basic-configuration-start-the-service-safely" tabindex="-1">Basic configuration: start the service safely <a class="header-anchor" href="#basic-configuration-start-the-service-safely" aria-label="Permalink to &quot;Basic configuration: start the service safely&quot;">​</a></h1><p>This page answers one question: in an existing Ershu development workspace, or an environment where the modules are already installed, what is the minimum configuration the API needs to start safely?</p><p>The backend still pins Core to a private Git source. This page therefore does not claim that a fresh installation can currently be completed using public packages alone.</p><h2 id="prepare-three-external-services" tabindex="-1">Prepare three external services <a class="header-anchor" href="#prepare-three-external-services" aria-label="Permalink to &quot;Prepare three external services&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Service</th><th>How the API uses it</th><th>Settings</th></tr></thead><tbody><tr><td>PostgreSQL</td><td>Stores accounts, projects, runs, documents, and system settings; the API reads it during startup</td><td><code>DATABASE_URL</code></td></tr><tr><td>Redis</td><td>Stores failed-login counters for login rate limiting</td><td><code>REDIS_URL</code></td></tr><tr><td>Milvus</td><td>Stores and queries vector indexes; the dependency health route connects to it</td><td><code>MILVUS_URI</code>, <code>MILVUS_TOKEN</code>, <code>MILVUS_DB_NAME</code></td></tr></tbody></table><p>The database is part of API startup. Redis is connected when login rate limiting is first used. Milvus is used by retrieval and the dependency check. A running process does not prove that all three services are available.</p><h2 id="write-a-minimal-development-configuration" tabindex="-1">Write a minimal development configuration <a class="header-anchor" href="#write-a-minimal-development-configuration" aria-label="Permalink to &quot;Write a minimal development configuration&quot;">​</a></h2><p>API and Core use Pydantic Settings to read process environment variables and a file named <code>.env</code>. The following example is suitable for local development. Every value in angle brackets must be replaced rather than copied literally.</p><div class="language-dotenv vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ENVIRONMENT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">development</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">LOG_LEVEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">INFO</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">DATABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">postgresql+asyncpg://ershu:&lt;database-password&gt;@localhost:5432/ershu</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">REDIS_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">redis://localhost:6379/0</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">MILVUS_URI</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://localhost:19530</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">MILVUS_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">MILVUS_DB_NAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">default</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SECRET_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;independent-random-value-at-least-32-characters&gt;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ENCRYPTION_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;different-random-value-at-least-32-characters&gt;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">MCP_KEY_PEPPER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;third-random-value-at-least-32-characters&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">127.0.0.1</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">8000</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">CORS_ORIGINS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://localhost:3000&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SESSION_COOKIE_SECURE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">false</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SESSION_COOKIE_SAMESITE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lax</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">REPOSITORY_STORAGE_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.ershu/repo_cache</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">TRUSTED_LOCAL_PATHS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[]</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ALLOW_DEV_OPEN_LOCAL_REPOSITORY_PATHS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">false</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">GIT_ALLOWED_HOSTS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br></div></div><p>Generate the three server-side secrets independently. Each must contain at least 32 characters, and weak values such as <code>change-me</code> and <code>replace-me</code> are rejected. In an existing API development environment, the following command generates one random value. Run it three times and assign each result to a different setting.</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import secrets; print(secrets.token_urlsafe(48))&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The command only prints text; it does not update <code>.env</code>. Never commit the generated values to Git.</p><h2 id="understand-why-these-values-matter" tabindex="-1">Understand why these values matter <a class="header-anchor" href="#understand-why-these-values-matter" aria-label="Permalink to &quot;Understand why these values matter&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th><th>Direct result of a bad value</th></tr></thead><tbody><tr><td><code>SECRET_KEY</code></td><td>Signs access and CSRF tokens</td><td>API creation rejects a weak value; rotating it invalidates existing login state</td></tr><tr><td><code>ENCRYPTION_KEY</code></td><td>Encrypts sensitive values stored in the database</td><td>API creation rejects a weak value; rotating it can make old ciphertext unreadable</td></tr><tr><td><code>MCP_KEY_PEPPER</code></td><td>Keys the server-side digest for MCP keys</td><td>API creation rejects a weak value; rotating it invalidates all existing MCP keys</td></tr><tr><td><code>DATABASE_URL</code></td><td>Selects the shared relational database</td><td>The API lifespan cannot complete its startup database read</td></tr><tr><td><code>CORS_ORIGINS</code></td><td>Lists browser origins allowed to send credentialed API requests</td><td>Browser requests from a different origin are blocked</td></tr><tr><td><code>REPOSITORY_STORAGE_PATH</code></td><td>Holds remote repository caches</td><td>Later clone, fetch, and cache maintenance operations use the wrong location</td></tr></tbody></table><p><code>OPAQUE_SERVER_SETUP</code> is long-lived server material for the password login protocol. When it is empty in development, the API creates material in the database and encrypts it with <code>ENCRYPTION_KEY</code>. Production rejects an empty or weak value and requires stable, correctly encoded material. The current source does not expose a project command that generates it, so a deployment process must generate and protect it separately; do not rely on the nonexistent function named by an older example.</p><h2 id="tighten-four-settings-in-production" tabindex="-1">Tighten four settings in production <a class="header-anchor" href="#tighten-four-settings-in-production" aria-label="Permalink to &quot;Tighten four settings in production&quot;">​</a></h2><p>When <code>ENVIRONMENT</code> is <code>prod</code> or <code>production</code>, source validation also enforces:</p><ul><li><code>SESSION_COOKIE_SECURE=true</code>;</li><li><code>SESSION_COOKIE_SAMESITE</code> is one of <code>lax</code>, <code>strict</code>, or <code>none</code>;</li><li><code>OPAQUE_SERVER_SETUP</code> is present and passes the strength check;</li><li><code>ALLOW_DEV_OPEN_LOCAL_REPOSITORY_PATHS=false</code>.</li></ul><p>Production requests under <code>/api/</code> and <code>/mcp</code> must also use HTTPS. If a reverse proxy terminates TLS, check <code>PROXY_HEADERS</code> and <code>FORWARDED_ALLOW_IPS</code> and trust only the real proxy addresses.</p><h2 id="verify-the-configuration-before-and-after-startup" tabindex="-1">Verify the configuration before and after startup <a class="header-anchor" href="#verify-the-configuration-before-and-after-startup" aria-label="Permalink to &quot;Verify the configuration before and after startup&quot;">​</a></h2><p>In an API repository where dependencies are already installed, upgrade the database and start the service:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> head</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-api</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>These are project entry points, not a claim that they have succeeded in your environment. A correct setup should meet each of these conditions:</p><ol><li>The API no longer reports weak server secrets, insecure production cookies, or a production-only local-path escape hatch.</li><li><code>GET http://127.0.0.1:8000/health</code> returns <code>{&quot;status&quot;:&quot;ok&quot;}</code>.</li><li>In <code>GET http://127.0.0.1:8000/api/v1/health/dependencies</code>, the top-level <code>status</code> is <code>ok</code>, while both <code>database.ok</code> and <code>milvus.ok</code> are <code>true</code>.</li><li>If step 2 succeeds but step 3 reports <code>degraded</code>, only the API process is alive. Fix the database or Milvus before treating the deployment as ready.</li></ol><p>The dependency route does not check Redis. To verify the full login path, complete a real login attempt as well. If Redis is unavailable, login rate limiting reports a service-unavailable error.</p><h2 id="source-locations" tabindex="-1">Source locations <a class="header-anchor" href="#source-locations" aria-label="Permalink to &quot;Source locations&quot;">​</a></h2><ul><li><code>core/src/ershu/core/config.py</code>: shared settings, defaults, secret checks, and production validation.</li><li><code>api/src/ershu/api/runtime_settings.py</code>: API settings, ranges, and production validation.</li><li><code>api/src/ershu/api_main.py</code>: startup, HTTPS, CORS, CSRF, and the liveness route.</li><li><code>api/src/ershu/api/routes/health.py</code>: database and Milvus dependency response.</li><li><code>api/src/ershu/api/services/auth/login_limits.py</code>: Redis-backed login rate limiting.</li><li><code>api/.env.example</code>: current environment-variable inventory; its old <code>OPAQUE_SERVER_SETUP</code> generation function does not exist and must not be copied.</li><li><code>api/pyproject.toml</code>: the <code>ershu-api</code> command and the currently pinned private Core source.</li></ul>`,27)])])}const u=s(n,[["render",r]]);export{k as __pageData,u as default};
